CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(120) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE devices (id CHAR(36) PRIMARY KEY,user_id BIGINT UNSIGNED NULL,label VARCHAR(120) NOT NULL,platform VARCHAR(40) NOT NULL DEFAULT 'unknown',credential_hash CHAR(64) NOT NULL UNIQUE,last_seen_at DATETIME NULL,revoked_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id,revoked_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE device_sessions (id CHAR(36) PRIMARY KEY,device_id CHAR(36) NOT NULL,session_hash CHAR(64) NOT NULL UNIQUE,connected_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE,INDEX(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE connection_requests (id CHAR(36) PRIMARY KEY,source_device CHAR(36) NOT NULL,target_device CHAR(36) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,INDEX(target_device,status,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE signaling_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id CHAR(36) NOT NULL,sender_device CHAR(36) NOT NULL,recipient_device CHAR(36) NOT NULL,envelope MEDIUMBLOB NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,INDEX(recipient_device,id),INDEX(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE guest_sessions (id CHAR(36) PRIMARY KEY,secret_hash CHAR(64) NOT NULL,device_a CHAR(36) NOT NULL,device_b CHAR(36) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,INDEX(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
